package com.rohit.inventory.service;
import com.rohit.inventory.event.DomainEvent; import com.rohit.inventory.repository.InventoryRepository; import org.springframework.stereotype.Component; import org.springframework.transaction.event.TransactionPhase; import org.springframework.transaction.event.TransactionalEventListener;
@Component public class DomainEventListener { private final AlertService alerts; private final NotificationService notifications; private final InventoryRepository inventory; public DomainEventListener(AlertService alerts,NotificationService notifications,InventoryRepository inventory){this.alerts=alerts;this.notifications=notifications;this.inventory=inventory;}
 @TransactionalEventListener(phase=TransactionPhase.AFTER_COMMIT) public void onEvent(DomainEvent e){try{if(e.eventType().startsWith("STOCK_")||e.eventType().startsWith("ADJUSTMENT_")){inventory.findById(e.entityId()).ifPresent(i->alerts.evaluate(i.getWarehouse().getId(),i.getProduct().getId(),i.getAvailableQuantity()));} if(e.eventType().startsWith("TRANSFER_")){notifications.create(e.eventType(),com.rohit.inventory.entity.Notification.Severity.INFO,e.eventType().replace('_',' '),"Transfer event "+e.entityId(),null,null,e.entityType(),e.entityId());}}catch(Exception ignored){/* notifications are best effort and never corrupt business state */}}
}
